import sys
sys.setrecursionlimit(10**6)

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        T_str = next(iterator)
    except StopIteration:
        return
    T = int(T_str)

    out_lines = []

    for _ in range(T):
        N = int(next(iterator))
        Q = int(next(iterator))

        A = [0] * (N + 1)
        for i in range(1, N + 1):
            A[i] = int(next(iterator))

        adj = [[] for _ in range(N + 1)]
        for _ in range(N - 1):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)
            adj[v].append(u)

        parent = [0] * (N + 1)
        depth = [0] * (N + 1)
        up = [[0] * 20 for _ in range(N + 1)]
        path_nodes = []

        def dfs(u, p, d):
            parent[u] = p
            depth[u] = d
            up[u][0] = p
            for k in range(1, 20):
                if up[u][k-1] != 0:
                    up[u][k] = up[up[u][k-1]][k-1]
                else:
                    up[u][k] = 0

            for v in adj[u]:
                if v != p:
                    dfs(v, u, d + 1)

        dfs(1, 0, 0)

        def get_lca(u, v):
            if depth[u] < depth[v]:
                u, v = v, u

            diff = depth[u] - depth[v]
            for k in range(20):
                if (diff >> k) & 1:
                    u = up[u][k]

            if u == v:
                return u

            for k in range(19, -1, -1):
                if up[u][k] != up[v][k]:
                    u = up[u][k]
                    v = up[v][k]

            return parent[u]

        def collect_path(a, b):
            lca = get_lca(a, b)
            vals = []

            curr = a
            while curr != lca:
                vals.append(A[curr])
                curr = parent[curr]
            vals.append(A[lca])

            curr = b
            while curr != lca:
                vals.append(A[curr]) # We will reverse this part later or just sort
                curr = parent[curr]

            vals.sort()
            return vals

        for _ in range(Q):
            a = int(next(iterator))
            b = int(next(iterator))

            vals = collect_path(a, b)

            min_diff = float('inf')
            for i in range(len(vals) - 1):
                diff = vals[i+1] - vals[i]
                if diff < min_diff:
                    min_diff = diff
                    if min_diff == 0:
                        break

            out_lines.append(str(min_diff))

    sys.stdout.write('\n'.join(out_lines) + '\n')

solve()
